/* Base & Reset */
:root {
  --primary-black: #0A0A0A;
  --text-white: #FFFFFF;
  --text-gray: #808080;
  --accent-color: #2563EB;
  --border-color: rgba(255, 255, 255, 0.1);
  --font-family: 'Inter', sans-serif;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body.dark-mode {
  background-color: var(--primary-black);
  color: var(--text-white);
  font-family: var(--font-family);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 5%;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul {
  list-style: none;
}

/* Typography */
h1 {
  font-size: clamp(3rem, 5vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 1.5rem;
}

h2 {
  font-size: clamp(2.5rem, 4vw, 4rem);
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 1rem;
}

h3 {
  font-size: 1.5rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
}

h4 {
  font-size: 1.25rem;
  font-weight: 400;
  color: var(--text-gray);
  margin-bottom: 1rem;
}

p {
  font-size: 1.125rem;
  color: #CCCCCC;
  margin-bottom: 1.5rem;
}

.subtitle {
  font-size: 1.25rem;
  color: var(--text-gray);
  max-width: 800px;
  margin: 0 auto 3rem;
}

.text-center {
  text-align: center;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.875rem 2rem;
  border-radius: 999px;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: var(--transition);
}

.btn-primary {
  background-color: var(--text-white);
  color: var(--primary-black);
}

.btn-primary:hover {
  background-color: #E5E5E5;
  transform: translateY(-2px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-white);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--text-white);
}

.btn-text {
  background: none;
  color: var(--text-gray);
  padding: 0.5rem 1rem;
}
.btn-text:hover {
  color: var(--text-white);
}

/* Section Spacing */
.section {
  padding: 8rem 0;
  border-top: 1px solid var(--border-color);
}

/* Navigation */
.navbar {
  position: fixed;
  top: 0;
  width: 100%;
  padding: 1.5rem 0;
  background-color: rgba(10, 10, 10, 0.9);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-white);
}

.nav-links a:hover {
  color: var(--text-gray);
}

/* Language Dropdown */
.lang-dropdown {
  position: relative;
}

.lang-btn {
  background: none;
  border: none;
  color: var(--text-white);
  font-size: 0.875rem;
  font-family: inherit;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.lang-menu {
  position: absolute;
  top: 100%;
  right: 0;
  background-color: #1A1A1A;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.5rem 0;
  min-width: 150px;
  display: none;
  margin-top: 1rem;
}

.lang-menu.show {
  display: block;
}

.lang-menu li a {
  display: block;
  padding: 0.75rem 1.5rem;
  color: var(--text-gray);
}

.lang-menu li a:hover {
  color: var(--text-white);
  background-color: rgba(255, 255, 255, 0.05);
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  width: 30px;
  height: 20px;
  position: relative;
}

.menu-toggle span {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--text-white);
  position: absolute;
  left: 0;
  transition: var(--transition);
}

.menu-toggle span:first-child {
  top: 0;
}

.menu-toggle span:last-child {
  bottom: 0;
}

/* Hero Section */
.hero {
  position: relative;
  height: 100vh;
  min-height: 600px;
  display: flex;
  align-items: flex-end;
  padding-bottom: 6rem;
}

.hero-carousel {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
}

.hero-slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  opacity: 0;
  transition: opacity 0.8s ease-in-out;
  display: flex;
  align-items: flex-end;
  padding-bottom: 8rem;
}

.hero-slide.active {
  opacity: 1;
  z-index: 1;
}

.hero-content {
  max-width: 800px;
}

.hero-controls {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}

.hero-indicators {
  display: flex;
  gap: 1rem;
}

.indicator {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.3);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.indicator.active {
  background-color: var(--text-white);
  transform: scale(1.2);
}

.hero-nav button {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-white);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  font-size: 1.5rem;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 0.5rem;
}

.hero-nav button:hover {
  background-color: var(--text-white);
  color: var(--primary-black);
}

/* Global Studios */
.region-tabs {
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-bottom: 4rem;
  flex-wrap: wrap;
}

.tab-btn {
  background: none;
  border: none;
  color: var(--text-gray);
  font-size: 1.25rem;
  font-weight: 500;
  cursor: pointer;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid transparent;
  transition: var(--transition);
}

.tab-btn:hover {
  color: var(--text-white);
}

.tab-btn.active {
  color: var(--text-white);
  border-bottom-color: var(--text-white);
}

.team-carousel-wrapper {
  position: relative;
  overflow: hidden;
  padding-bottom: 2rem;
}

.team-carousel {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.team-carousel::-webkit-scrollbar {
  display: none;
}

.team-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background-color: #111;
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
}

.team-photo {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background-color: #333;
  margin-bottom: 1.5rem;
  background-size: cover;
  background-position: center;
}

.team-quote {
  font-size: 1rem;
  font-style: italic;
  margin-bottom: 2rem;
  flex-grow: 1;
}

.team-info h4 {
  color: var(--text-white);
  margin-bottom: 0.25rem;
}

.team-info p {
  font-size: 0.875rem;
  color: var(--text-gray);
  margin-bottom: 1rem;
}

.team-cta {
  font-size: 0.875rem;
  color: var(--text-white);
  text-decoration: underline;
  text-underline-offset: 4px;
}

.team-nav {
  display: flex;
  justify-content: flex-end;
  margin-top: 1rem;
  gap: 1rem;
}
.team-nav button {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-white);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}
.team-nav button:hover {
  background-color: var(--text-white);
  color: var(--primary-black);
}

/* Work Section */
.work-section {
  overflow: hidden;
}

.work-carousel-container {
  padding-left: 5%;
  margin-top: 3rem;
}

.work-carousel {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding-right: 5%;
  padding-bottom: 2rem;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.work-carousel::-webkit-scrollbar {
  display: none;
}

.work-card {
  flex: 0 0 500px;
  scroll-snap-align: start;
}

.work-image {
  width: 100%;
  height: 350px;
  background-color: #222;
  border-radius: 12px;
  margin-bottom: 1.5rem;
  background-size: cover;
  background-position: center;
}

.work-content h3 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.work-content h4 {
  font-size: 1.25rem;
  color: var(--text-white);
  margin-bottom: 1rem;
}

.work-content .quote {
  font-size: 1rem;
  color: var(--text-gray);
  font-style: italic;
  margin-bottom: 0.5rem;
}

.work-content .author {
  font-size: 0.875rem;
  color: var(--text-gray);
}

/* How We Work */
.hww-section {
  background-color: #111;
}

.hww-content {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.hww-content h2 {
  margin-bottom: 2rem;
}

.hww-content p {
  font-size: 1.5rem;
  margin-bottom: 3rem;
  line-height: 1.5;
}

/* Latest Insights */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
  margin-top: 4rem;
}

.insight-card {
  padding: 2rem;
  background-color: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.insight-card:hover {
  background-color: rgba(255, 255, 255, 0.05);
  transform: translateY(-5px);
}

.tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-gray);
  margin-bottom: 1rem;
  display: inline-block;
}

.insight-card h3 {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  flex-grow: 1;
}

.insight-link {
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

/* Our Principles */
.principles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 3rem;
  margin-top: 4rem;
}

.principle-item h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1rem;
}

.principle-item p {
  font-size: 1rem;
  color: var(--text-gray);
}

/* CTA Banner */
.cta-banner {
  background-color: var(--text-white);
  color: var(--primary-black);
}
.cta-banner h2 {
  color: var(--primary-black);
}
.cta-banner p {
  color: #333;
  max-width: 700px;
  margin: 0 auto 2rem;
}
.cta-banner .btn-primary {
  background-color: var(--primary-black);
  color: var(--text-white);
}
.cta-banner .btn-primary:hover {
  background-color: #333;
}

/* Footer */
.footer {
  padding: 6rem 0 3rem;
  background-color: #050505;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  margin-bottom: 6rem;
}

.footer-cta h4 {
  color: var(--text-white);
  font-size: 2rem;
  margin-bottom: 1rem;
}

.footer-cta p {
  margin-bottom: 2rem;
}

.footer-nav {
  display: flex;
  gap: 2rem;
  margin-bottom: 4rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 2rem;
}

.footer-nav a {
  font-size: 1.25rem;
  font-weight: 500;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem;
}

.footer-bottom p {
  margin: 0;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 1.5rem;
}

.footer-legal a {
  font-size: 0.875rem;
  color: var(--text-gray);
}

.footer-legal a:hover {
  color: var(--text-white);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 2rem;
  left: 5%;
  right: 5%;
  background-color: #1A1A1A;
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem 2rem;
  z-index: 9999;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  transform: translateY(150%);
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  gap: 2rem;
}

.cookie-content p {
  margin: 0;
  font-size: 0.875rem;
}

.cookie-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero h1 {
    font-size: 3.5rem;
  }
  .work-card {
    flex: 0 0 400px;
  }
  .footer-top {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    position: fixed;
    top: 0;
    right: -100%;
    width: 80%;
    max-width: 400px;
    height: 100vh;
    background-color: #111;
    flex-direction: column;
    padding: 6rem 2rem;
    transition: var(--transition);
    align-items: flex-start;
  }

  .nav-links.active {
    right: 0;
  }

  .menu-toggle {
    display: block;
    z-index: 1001;
  }
  .menu-toggle.active span:first-child {
    transform: rotate(45deg) translate(5px, 5px);
  }
  .menu-toggle.active span:last-child {
    transform: rotate(-45deg) translate(5px, -5px);
  }

  .work-card {
    flex: 0 0 300px;
  }

  .cookie-content {
    flex-direction: column;
    align-items: flex-start;
  }

  .cookie-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

